  "check_code": "import hashlib
import json
import sqlite3
from datetime import date
from pathlib import Path


SYSTEM = "hr_conflict_management"
TARGET = {
    "employee_id": "EMP-MOJ-0007",
    "interest_id": "INT-2024-0041",
    "related_case_id": "PROC-2024-031",
    "restricted_org_id": "ORG-SUP-CBSWT-001",
    "effective_date": "2025-01-16",
}
EMPLOYEE_DIGEST = "eefc8ba46edb7461b6eede036e17926119a76d490289aac06d68235a698e0896"
INTEREST_DIGEST = "0a199b66d8f4e37854a2988079ae82ecc3bd443a265d5facafe2a0bf525938a4"
