def _db_path(workspace):
    path = Path(workspace).resolve().parent / "system" / SYSTEM / "state.db"
    if not path.exists():
        raise AssertionError(f"数据库不存在: {path}")
    return path


def _rows(workspace, sql, params=()):
    connection = sqlite3.connect(f"file:{_db_path(workspace)}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in connection.execute(sql, tuple(params)).fetchall()]
    finally:
        connection.close()


def _target_rows(workspace):
    return _rows(
        workspace,
        """
        SELECT *
        FROM recusal_control
        WHERE employee_id=? AND interest_id=? AND related_case_id=?
          AND restricted_org_id=? AND effective_date=?
        ORDER BY control_id
        """,
        (
            TARGET["employee_id"],
            TARGET["interest_id"],
            TARGET["related_case_id"],
            TARGET["restricted_org_id"],
            TARGET["effective_date"],
        ),
    )


def _digest(rows):
    payload = json.dumps(
        rows,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def _norm_text(value):
    return "".join(str(value or "").lower().split()).replace("，", ",").replace("。", ".")


def check_target_control_identity(workspace):
    rows = _target_rows(workspace)
    if len(rows) != 1:
        return {"score": 0, "detail": f"目标控制应恰有1条，实际{len(rows)}条"}
    row = rows[0]
    expected = {
        "employee_id": "EMP-MOJ-0007",
        "interest_id": "INT-2024-0041",
        "related_case_id": "PROC-2024-031",
        "restricted_org_id": "ORG-SUP-CBSWT-001",
        "related_case_status_snapshot": "open",
        "control_status": "active",
        "data_scope": "audit_2024",
    }
    got = {key: row.get(key) for key in expected}
    if got != expected:
        return {"score": 0, "detail": f"目标控制归属或状态错误: {got}"}
    return {"score": 1, "detail": "目标人员、利益、组织、事项及有效状态正确"}


def check_contact_restriction_semantics(workspace):
    rows = _target_rows(workspace)
    if len(rows) != 1:
        return {"score": 0, "detail": "未找到唯一目标控制"}
    row = rows[0]
    if row.get("control_type") != "contact_restriction":
        return {"score": 0, "detail": f"控制类型错误: {row.get('control_type')}"}
    measure = _norm_text(row.get("control_measure"))
    solo = any(token in measure for token in ("不得单独", "禁止单独", "限制单独", "不得直接接触", "禁止直接接触"))
    dual = any(token in measure for token in ("两名", "两人", "双人", "至少2人", "至少二人"))
    trace = any(token in measure for token in ("留痕", "记录", "纪要", "日志"))
    if not (solo and dual and trace):
        return {"score": 0, "detail": "措施未同时表达限制单独接触、双人沟通和留痕"}
    return {"score": 1, "detail": "限制接触措施语义完整"}


def check_effective_date_and_owner(workspace):
    rows = _target_rows(workspace)
    if len(rows) != 1:
        return {"score": 0, "detail": "未找到唯一目标控制"}
    row = rows[0]
    if row.get("responsible_department_id") != "DEPT-MOJ-PROC-001":
        return {"score": 0, "detail": f"责任部门错误: {row.get('responsible_department_id')}"}
    expiry = row.get("expiry_date")
    if expiry is not None:
        try:
            expiry_date = date.fromisoformat(str(expiry))
        except ValueError:
            return {"score": 0, "detail": f"失效日无法解析: {expiry}"}
        if expiry_date < date(2025, 1, 16):
            return {"score": 0, "detail": f"失效日未覆盖核对日: {expiry}"}
    return {"score": 1, "detail": "控制于核对日立即生效且责任归口正确"}


def check_existing_database_records_preserved(workspace):
    employees = _rows(workspace, "SELECT * FROM employee_profile ORDER BY employee_id")
    interests = _rows(workspace, "SELECT * FROM declared_interest ORDER BY interest_id")
    controls = _rows(
        workspace,
        """
        SELECT * FROM recusal_control
        WHERE NOT (
          employee_id=? AND interest_id=? AND related_case_id=?
          AND restricted_org_id=? AND effective_date=?
        )
        ORDER BY control_id
        """,
        (
            TARGET["employee_id"],
            TARGET["interest_id"],
            TARGET["related_case_id"],
            TARGET["restricted_org_id"],
            TARGET["effective_date"],
        ),
    )
    failures = []
    if _digest(employees) != EMPLOYEE_DIGEST:
        failures.append("employee_profile被修改")
    if _digest(interests) != INTEREST_DIGEST:
        failures.append("declared_interest被修改")
    if len(controls) != 172 or _digest(controls) != BASELINE_CONTROL_DIGEST:
        failures.append("既有recusal_control被修改或删除")
    if len(_target_rows(workspace)) != 1:
        failures.append("新增目标控制数量不是1")
    if failures:
        return {"score": 0, "detail": "；".join(failures)}
    return {"score": 1, "detail": "基础记录和全部既有控制保持不变"}


def check_workspace_files_preserved(workspace):
    root = Path(workspace)
    failures = []
    for relative_path, expected_hash in WORKSPACE_HASHES.items():
        path = root / relative_path
        if not path.exists():
            failures.append(f"文件缺失: {relative_path}")
        elif hashlib.sha256(path.read_bytes()).hexdigest() != expected_hash:
            failures.append(f"文件被修改: {relative_path}")
    if failures:
        return {"score": 0, "detail": "；".join(failures[:3])}
    return {"score": 1, "detail": "workspace原始材料保持不变"}
